test("um cupom de 10% baixa 200 para 180", () => {
	// Arrange: preparar a situação
	const cart = new Cart([{ price: 200 }]);
	// Act: fazer a única coisa que está sendo testada
	const total = cart.totalWith("TEN");
	// Assert: comparar com o esperado
	expect(total).toBe(180);
});

